let file = """{"version":3,"file":"initHostTelemetry-CqU3RsMC.js","names":[],"sources":["../../packages/account-core/src/core/billing/telemetry/billingTelemetryEvent.ts","../../packages/account-core/src/core/billing/telemetry/payload.ts","../../src/platform/telemetry/TelemetryRegistry.ts","../../src/platform/telemetry/utils/surveyNormalization.ts","../../src/platform/telemetry/providers/host/HostTelemetrySink.ts","../../src/platform/telemetry/initHostTelemetry.ts"],"sourcesContent":["import type { CancelBillingEvent } from './cancelEvent.js'\nimport type { CapabilityReadBillingEvent } from './capabilityReadEvent.js'\nimport type { CheckoutChallengeBillingEvent } from './checkoutChallengeEvent.js'\nimport type { CheckoutRedirectBillingEvent } from './checkoutRedirectEvent.js'\nimport type { DowngradeToPersonalBillingEvent } from './downgradeToPersonalEvent.js'\nimport type { EntryBillingEvent } from './entryEvent.js'\nimport type { BillingOperationBillingEvent } from './operationEvent.js'\nimport type { PortalBillingEvent } from './portalEvent.js'\nimport type { ResubscribeBillingEvent } from './resubscribeEvent.js'\nimport type { SubscriptionCheckoutBillingEvent } from './subscriptionCheckoutEvent.js'\nimport type { TopupBillingEvent } from './topupEvent.js'\nimport type { WebEntryBillingEvent } from './webEntryEvent.js'\nimport type { WebHandoffBillingEvent } from './webHandoffEvent.js'\nimport type { WebReturnBillingEvent } from './webReturnEvent.js'\nimport type { WebSessionBillingEvent } from './webSessionEvent.js'\n\nexport type BillingSurface = 'cloud_app' | 'billing_web'\n\nexport type BillingClient = 'sdk' | 'legacy'\n\nexport type BillingTelemetryEvent = {\n  /** The rail of the code that emitted the event; absent when the emitter does not know it. */\n  billing_client?: BillingClient\n} & (\n  | CapabilityReadBillingEvent\n  | SubscriptionCheckoutBillingEvent\n  | BillingOperationBillingEvent\n  | ResubscribeBillingEvent\n  | TopupBillingEvent\n  | DowngradeToPersonalBillingEvent\n  | WebEntryBillingEvent\n  | WebHandoffBillingEvent\n  | WebReturnBillingEvent\n  | WebSessionBillingEvent\n  | EntryBillingEvent\n  | CancelBillingEvent\n  | PortalBillingEvent\n  | CheckoutChallengeBillingEvent\n  | CheckoutRedirectBillingEvent\n)\n\ntype BillingTelemetryEventNameFor<T extends BillingTelemetryEvent> =\n  T extends BillingTelemetryEvent\n    ? `billing.${T['operation']}.${T['stage']}`\n    : never\n\nexport type BillingTelemetryEventName =\n  BillingTelemetryEventNameFor<BillingTelemetryEvent>\n\nexport function getBillingTelemetryEventName(\n  event: BillingTelemetryEvent\n): BillingTelemetryEventName {\n  return `billing.${event.operation}.${event.stage}` as BillingTelemetryEventName\n}\n","import type {\n  BillingSurface,\n  BillingTelemetryEvent\n} from './billingTelemetryEvent.js'\n\ntype BillingTelemetryPayload = Record<string, unknown>\n\ntype KeysOfUnion<T> = T extends unknown ? keyof T : never\n\nexport type BillingPayloadFieldHandling<Event = BillingTelemetryEvent> = Record<\n  Exclude<KeysOfUnion<Event>, 'operation' | 'stage' | 'outcome'>,\n  'optional' | 'required'\n>\n\nexport const BILLING_PAYLOAD_FIELD_HANDLING = {\n  checkout_status: 'required',\n  control: 'required',\n  correlation_id: 'required',\n  destination: 'required',\n  failure_category: 'required',\n  has_plan: 'required',\n  intent: 'required',\n  member_removal_count: 'required',\n  member_removal_failures: 'required',\n  mode: 'required',\n  navigation: 'required',\n  operation_type: 'required',\n  origin: 'required',\n  product: 'required',\n  reason: 'required',\n  result: 'required',\n  source: 'required',\n  step: 'required',\n  target: 'required',\n  to: 'required',\n  amount_cents: 'optional',\n  amount_preset: 'optional',\n  billing_client: 'optional',\n  billing_op_id: 'optional',\n  checkout_attempt_id: 'optional',\n  checkout_type: 'optional',\n  checkout_ui: 'optional',\n  current_tier: 'optional',\n  cycle: 'optional',\n  decline_reason: 'optional',\n  duration_ms: 'optional',\n  error_code: 'optional',\n  method_kind: 'optional',\n  payment_intent_source: 'optional',\n  presentation: 'optional',\n  recovery_outcome: 'optional',\n  resumed: 'optional',\n  target_tier: 'optional',\n  tier: 'optional'\n} as const satisfies BillingPayloadFieldHandling\n\nconst OPTIONAL_BILLING_PAYLOAD_FIELDS = Object.entries(\n  BILLING_PAYLOAD_FIELD_HANDLING\n).flatMap(([field, handling]) => (handling === 'optional' ? [field] : []))\n\nconst REQUIRED_BILLING_PAYLOAD_FIELDS = Object.entries(\n  BILLING_PAYLOAD_FIELD_HANDLING\n).flatMap(([field, handling]) => (handling === 'required' ? [field] : []))\n\nconst optionalBillingPayloadFields: ReadonlySet<string> = new Set(\n  OPTIONAL_BILLING_PAYLOAD_FIELDS\n)\nconst requiredBillingPayloadFields: ReadonlySet<string> = new Set(\n  REQUIRED_BILLING_PAYLOAD_FIELDS\n)\n\nexport function getBillingTelemetryEventPayload(event: BillingTelemetryEvent) {\n  const payload: BillingTelemetryPayload = {\n    operation: event.operation,\n    stage: event.stage,\n    outcome: event.outcome\n  }\n\n  for (const [field, value] of Object.entries(event)) {\n    if (requiredBillingPayloadFields.has(field)) {\n      payload[field] = value\n    } else if (optionalBillingPayloadFields.has(field) && value !== undefined) {\n      payload[field] = value\n    }\n  }\n\n  return payload\n}\n\n/** Only the cloud build registers the sinks that call this; the desktop host sink claims no surface. */\nexport function getCloudAppBillingTelemetryEventPayload(\n  event: BillingTelemetryEvent\n): BillingTelemetryPayload & { billing_surface: BillingSurface } {\n  return {\n    ...getBillingTelemetryEventPayload(event),\n    billing_surface: 'cloud_app'\n  }\n}\n\n/** The payload billing web reports: the same allowlist, claiming the billing web surface. */\nexport function getBillingWebTelemetryEventPayload(\n  event: BillingTelemetryEvent\n): BillingTelemetryPayload & { billing_surface: BillingSurface } {\n  return {\n    ...getBillingTelemetryEventPayload(event),\n    billing_surface: 'billing_web'\n  }\n}\n","import type {\n  BillingTelemetryEvent,\n  CheckoutJourneyTelemetryEvent\n} from '@comfyorg/account-core/billing'\nimport type {\n  SsoTelemetryEvent,\n  WebSessionTelemetryEvent\n} from '@comfyorg/account-core/telemetry'\nimport type {\n  AddCreditsClickMetadata,\n  AgentAttachButtonClickedMetadata,\n  AgentConsentNotOfferedMetadata,\n  AgentConsentOfferExitedMetadata,\n  AgentConsentResolvedMetadata,\n  AgentConsentShownMetadata,\n  AgentCreditTransitionNoticeMetadata,\n  AgentPaywallCtaMetadata,\n  AgentPaywallShownMetadata,\n  AgentEntryButtonClickedMetadata,\n  AgentErrorMetadata,\n  AgentFreeUseExposureMetadata,\n  AgentFreeUseNoticeMetadata,\n  AgentGraphProjectionMetadata,\n  AgentMessageSentMetadata,\n  AgentMessageFeedbackMetadata,\n  AgentNodeTaggedMetadata,\n  AgentOnboardingNotShownMetadata,\n  AgentOnboardingStepMetadata,\n  AgentPanelClosedMetadata,\n  AgentPanelOpenedMetadata,\n  AgentRunApprovalResolvedMetadata,\n  AgentRunApprovalShownMetadata,\n  AgentRunModeChangedMetadata,\n  AgentStarterPromptClickedMetadata,\n  AgentStarterPromptExposureMetadata,\n  AgentStopClickedMetadata,\n  AgentThreadStartedMetadata,\n  AgentWorkflowBoundMetadata,\n  AgentWorkflowAppliedMetadata,\n  AuthErrorMetadata,\n  AuthMetadata,\n  BeginCheckoutMetadata,\n  BootstrapCompleteMetadata,\n  DefaultViewSetMetadata,\n  EnterLinearMetadata,\n  ExecutionErrorMetadata,\n  ExecutionOutcomeMetadata,\n  ExecutionSuccessMetadata,\n  HelpCenterClosedMetadata,\n  HelpCenterOpenedMetadata,\n  HelpResourceClickedMetadata,\n  ImageLoadFailureMetadata,\n  InAppSurveyEvent,\n  InAppSurveyStage,\n  LinkDedupDropMetadata,\n  NamedValuesShadowDiffMismatchMetadata,\n  NamedValuesShadowDiffSummaryMetadata,\n  NodeAddedMetadata,\n  NodeSearchMetadata,\n  NodeSearchResultMetadata,\n  OnboardingTourMetadata,\n  OnboardingTourNudgeMetadata,\n  OnboardingTourNudgeStage,\n  OnboardingTourStage,\n  OnboardingTourStepMetadata,\n  OnboardingTourStepStage,\n  SearchQueryMetadata,\n  PageViewMetadata,\n  PageVisibilityMetadata,\n  ResubscribeClickMetadata,\n  RunButtonProperties,\n  ShareFlowMetadata,\n  ShareLinkOpenedMetadata,\n  SettingChangedMetadata,\n  SharedWorkflowRunMetadata,\n  ShellLayoutMetadata,\n  SubscriptionCancellationMetadata,\n  SubscriptionMetadata,\n  SubscriptionSuccessMetadata,\n  SurveyResponses,\n  TabCountMetadata,\n  TelemetryDispatcher,\n  TelemetryProvider,\n  FetchTimeoutMetadata,\n  TemplateFilterMetadata,\n  TemplateLibraryClosedMetadata,\n  TemplateLibraryMetadata,\n  TemplateMetadata,\n  UiButtonClickMetadata,\n  UnifiedAuthRefreshMetadata,\n  UnifiedAuthRetryMetadata,\n  WidgetFavoriteToggledMetadata,\n  WorkflowCreatedMetadata,\n  WorkflowImportMetadata,\n  WorkflowSavedMetadata,\n  WorkspaceInviteFailedMetadata,\n  WorkspaceInviteMetadata,\n  WorkspaceScopeMismatchMetadata,\n  WorkspaceTelemetryContext\n} from './types'\n\n/**\n * Registry that holds multiple telemetry providers and dispatches\n * all tracking calls to each registered provider.\n *\n * Implements TelemetryDispatcher (all methods required) while dispatching\n * to TelemetryProvider instances using optional chaining since providers\n * only implement the methods they care about.\n */\nexport class TelemetryRegistry implements TelemetryDispatcher {\n  private providers: TelemetryProvider[] = []\n\n  registerProvider(provider: TelemetryProvider): void {\n    this.providers.push(provider)\n  }\n\n  private dispatch(action: (provider: TelemetryProvider) => void): void {\n    this.providers.forEach((provider) => {\n      try {\n        action(provider)\n      } catch (error) {\n        console.error('[Telemetry] Provider dispatch failed', error)\n      }\n    })\n  }\n\n  trackSignupOpened(): void {\n    this.dispatch((provider) => provider.trackSignupOpened?.())\n  }\n\n  trackAuth(metadata: AuthMetadata): void {\n    this.dispatch((provider) => provider.trackAuth?.(metadata))\n  }\n\n  trackAuthFailed(metadata: AuthErrorMetadata): void {\n    this.dispatch((provider) => provider.trackAuthFailed?.(metadata))\n  }\n\n  trackUnifiedAuthRetry(metadata: UnifiedAuthRetryMetadata): void {\n    this.dispatch((provider) => provider.trackUnifiedAuthRetry?.(metadata))\n  }\n\n  trackUnifiedAuthRefresh(metadata: UnifiedAuthRefreshMetadata): void {\n    this.dispatch((provider) => provider.trackUnifiedAuthRefresh?.(metadata))\n  }\n\n  // fallow-ignore-next-line unused-class-member\n  trackWebSessionEvent(event: WebSessionTelemetryEvent): void {\n    this.dispatch((provider) => provider.trackWebSessionEvent?.(event))\n  }\n\n  trackSsoEvent(event: SsoTelemetryEvent): void {\n    this.dispatch((provider) => provider.trackSsoEvent?.(event))\n  }\n\n  trackImageLoadFailed(metadata: ImageLoadFailureMetadata): void {\n    this.dispatch((provider) => provider.trackImageLoadFailed?.(metadata))\n  }\n\n  trackBootstrapComplete(metadata: BootstrapCompleteMetadata): void {\n    this.dispatch((provider) => provider.trackBootstrapComplete?.(metadata))\n  }\n\n  trackFeatureFlagEvaluation(key: string, value: unknown): void {\n    this.dispatch((provider) =>\n      provider.trackFeatureFlagEvaluation?.(key, value)\n    )\n  }\n\n  trackUserLoggedIn(): void {\n    this.dispatch((provider) => provider.trackUserLoggedIn?.())\n  }\n\n  trackSubscription(\n    event: 'modal_opened' | 'subscribe_clicked',\n    metadata?: SubscriptionMetadata\n  ): void {\n    this.dispatch((provider) => provider.trackSubscription?.(event, metadata))\n  }\n\n  trackBeginCheckout(metadata: BeginCheckoutMetadata): void {\n    this.dispatch((provider) => provider.trackBeginCheckout?.(metadata))\n  }\n\n  trackMonthlySubscriptionSucceeded(\n    metadata?: SubscriptionSuccessMetadata\n  ): void {\n    this.dispatch((provider) =>\n      provider.trackMonthlySubscriptionSucceeded?.(metadata)\n    )\n  }\n\n  trackMonthlySubscriptionCancelled(): void {\n    this.dispatch((provider) => provider.trackMonthlySubscriptionCancelled?.())\n  }\n\n  trackSubscriptionCancellation(\n    event: 'flow_opened' | 'confirmed' | 'abandoned' | 'failed',\n    metadata?: SubscriptionCancellationMetadata\n  ): void {\n    this.dispatch((provider) =>\n      provider.trackSubscriptionCancellation?.(event, metadata)\n    )\n  }\n\n  trackResubscribeClicked(metadata: ResubscribeClickMetadata): void {\n    this.dispatch((provider) => provider.trackResubscribeClicked?.(metadata))\n  }\n\n  trackAddApiCreditButtonClicked(metadata?: AddCreditsClickMetadata): void {\n    this.dispatch((provider) =>\n      provider.trackAddApiCreditButtonClicked?.(metadata)\n    )\n  }\n\n  trackApiCreditTopupButtonPurchaseClicked(amount: number): void {\n    this.dispatch((provider) =>\n      provider.trackApiCreditTopupButtonPurchaseClicked?.(amount)\n    )\n  }\n\n  trackApiCreditTopupSucceeded(): void {\n    this.dispatch((provider) => provider.trackApiCreditTopupSucceeded?.())\n  }\n\n  trackWorkspaceInviteSent(metadata: WorkspaceInviteMetadata): void {\n    this.dispatch((provider) => provider.trackWorkspaceInviteSent?.(metadata))\n  }\n\n  trackWorkspaceInviteFailed(metadata: WorkspaceInviteFailedMetadata): void {\n    this.dispatch((provider) => provider.trackWorkspaceInviteFailed?.(metadata))\n  }\n\n  trackBillingEvent(event: BillingTelemetryEvent): void {\n    this.dispatch((provider) => provider.trackBillingEvent?.(event))\n  }\n\n  // fallow-ignore-next-line unused-class-member\n  setWorkspaceContext(context: WorkspaceTelemetryContext | undefined): void {\n    this.dispatch((provider) => provider.setWorkspaceContext?.(context))\n  }\n\n  // fallow-ignore-next-line unused-class-member\n  trackWorkspaceScopeMismatch(metadata: WorkspaceScopeMismatchMetadata): void {\n    this.dispatch((provider) =>\n      provider.trackWorkspaceScopeMismatch?.(metadata)\n    )\n  }\n\n  trackCheckoutJourneyEvent(event: CheckoutJourneyTelemetryEvent): void {\n    this.dispatch((provider) => provider.trackCheckoutJourneyEvent?.(event))\n  }\n\n  trackAgentPaywallShown(metadata: AgentPaywallShownMetadata): void {\n    this.dispatch((provider) => provider.trackAgentPaywallShown?.(metadata))\n  }\n\n  trackAgentPaywallCtaClicked(metadata: AgentPaywallCtaMetadata): void {\n    this.dispatch((provider) =>\n      provider.trackAgentPaywallCtaClicked?.(metadata)\n    )\n  }\n\n  trackAgentCreditTransitionNotice(\n    metadata: AgentCreditTransitionNoticeMetadata\n  ): void {\n    this.dispatch((provider) =>\n      provider.trackAgentCreditTransitionNotice?.(metadata)\n    )\n  }\n\n  trackRunButton(properties: RunButtonProperties): void {\n    this.dispatch((provider) => provider.trackRunButton?.(properties))\n  }\n\n  trackSurvey(\n    stage: 'opened' | 'submitted',\n    responses?: SurveyResponses\n  ): void {\n    this.dispatch((provider) => provider.trackSurvey?.(stage, responses))\n  }\n\n  // fallow-ignore-next-line unused-class-member\n  trackInAppSurvey(stage: InAppSurveyStage, event: InAppSurveyEvent): void {\n    this.dispatch((provider) => provider.trackInAppSurvey?.(stage, event))\n  }\n\n  trackOnboardingTour(\n    stage: OnboardingTourStepStage,\n    metadata: OnboardingTourStepMetadata\n  ): void\n  trackOnboardingTour(\n    stage: OnboardingTourNudgeStage,\n    metadata: OnboardingTourNudgeMetadata\n  ): void\n  trackOnboardingTour(\n    stage: OnboardingTourStage,\n    metadata: OnboardingTourMetadata\n  ): void {\n    this.dispatch((provider) => {\n      const track = provider.trackOnboardingTour as\n        | ((s: OnboardingTourStage, m: OnboardingTourMetadata) => void)\n        | undefined\n      track?.call(provider, stage, metadata)\n    })\n  }\n\n  trackEmailVerification(stage: 'opened' | 'requested' | 'completed'): void {\n    this.dispatch((provider) => provider.trackEmailVerification?.(stage))\n  }\n\n  trackTemplate(metadata: TemplateMetadata): void {\n    this.dispatch((provider) => provider.trackTemplate?.(metadata))\n  }\n\n  trackTemplateLibraryOpened(metadata: TemplateLibraryMetadata): void {\n    this.dispatch((provider) => provider.trackTemplateLibraryOpened?.(metadata))\n  }\n\n  trackTemplateLibraryClosed(metadata: TemplateLibraryClosedMetadata): void {\n    this.dispatch((provider) => provider.trackTemplateLibraryClosed?.(metadata))\n  }\n\n  trackWorkflowImported(metadata: WorkflowImportMetadata): void {\n    this.dispatch((provider) => provider.trackWorkflowImported?.(metadata))\n  }\n\n  trackWorkflowOpened(metadata: WorkflowImportMetadata): void {\n    this.dispatch((provider) => provider.trackWorkflowOpened?.(metadata))\n  }\n\n  trackWorkflowSaved(metadata: WorkflowSavedMetadata): void {\n    this.dispatch((provider) => provider.trackWorkflowSaved?.(metadata))\n  }\n\n  trackDefaultViewSet(metadata: DefaultViewSetMetadata): void {\n    this.dispatch((provider) => provider.trackDefaultViewSet?.(metadata))\n  }\n\n  trackEnterLinear(metadata: EnterLinearMetadata): void {\n    this.dispatch((provider) => provider.trackEnterLinear?.(metadata))\n  }\n\n  trackShareFlow(metadata: ShareFlowMetadata): void {\n    this.dispatch((provider) => provider.trackShareFlow?.(metadata))\n  }\n\n  trackShareLinkOpened(metadata: ShareLinkOpenedMetadata): void {\n    this.dispatch((provider) => provider.trackShareLinkOpened?.(metadata))\n  }\n\n  trackPageVisibilityChanged(metadata: PageVisibilityMetadata): void {\n    this.dispatch((provider) => provider.trackPageVisibilityChanged?.(metadata))\n  }\n\n  trackTabCount(metadata: TabCountMetadata): void {\n    this.dispatch((provider) => provider.trackTabCount?.(metadata))\n  }\n\n  trackShellLayout(metadata: ShellLayoutMetadata): void {\n    this.dispatch((provider) => provider.trackShellLayout?.(metadata))\n  }\n\n  trackNodeSearch(metadata: NodeSearchMetadata): void {\n    this.dispatch((provider) => provider.trackNodeSearch?.(metadata))\n  }\n\n  trackNodeSearchResultSelected(metadata: NodeSearchResultMetadata): void {\n    this.dispatch((provider) =>\n      provider.trackNodeSearchResultSelected?.(metadata)\n    )\n  }\n\n  trackSearchQuery(metadata: SearchQueryMetadata): void {\n    this.dispatch((provider) => provider.trackSearchQuery?.(metadata))\n  }\n\n  trackNodeAdded(metadata: NodeAddedMetadata): void {\n    this.dispatch((provider) => provider.trackNodeAdded?.(metadata))\n  }\n\n  trackTemplateFilterChanged(metadata: TemplateFilterMetadata): void {\n    this.dispatch((provider) => provider.trackTemplateFilterChanged?.(metadata))\n  }\n\n  trackHelpCenterOpened(metadata: HelpCenterOpenedMetadata): void {\n    this.dispatch((provider) => provider.trackHelpCenterOpened?.(metadata))\n  }\n\n  trackHelpResourceClicked(metadata: HelpResourceClickedMetadata): void {\n    this.dispatch((provider) => provider.trackHelpResourceClicked?.(metadata))\n  }\n\n  trackHelpCenterClosed(metadata: HelpCenterClosedMetadata): void {\n    this.dispatch((provider) => provider.trackHelpCenterClosed?.(metadata))\n  }\n\n  trackWorkflowCreated(metadata: WorkflowCreatedMetadata): void {\n    this.dispatch((provider) => provider.trackWorkflowCreated?.(metadata))\n  }\n\n  trackWorkflowExecution(): void {\n    this.dispatch((provider) => provider.trackWorkflowExecution?.())\n  }\n\n  trackExecutionOutcome(metadata: ExecutionOutcomeMetadata): void {\n    this.dispatch((provider) => provider.trackExecutionOutcome?.(metadata))\n  }\n\n  trackExecutionError(metadata: ExecutionErrorMetadata): void {\n    this.dispatch((provider) => provider.trackExecutionError?.(metadata))\n  }\n\n  trackExecutionSuccess(metadata: ExecutionSuccessMetadata): void {\n    this.dispatch((provider) => provider.trackExecutionSuccess?.(metadata))\n  }\n\n  trackSharedWorkflowRun(metadata: SharedWorkflowRunMetadata): void {\n    this.dispatch((provider) => provider.trackSharedWorkflowRun?.(metadata))\n  }\n\n  trackSettingChanged(metadata: SettingChangedMetadata): void {\n    this.dispatch((provider) => provider.trackSettingChanged?.(metadata))\n  }\n\n  trackUiButtonClicked(metadata: UiButtonClickMetadata): void {\n    this.dispatch((provider) => provider.trackUiButtonClicked?.(metadata))\n  }\n\n  trackAgentMessageFeedback(metadata: AgentMessageFeedbackMetadata): void {\n    this.dispatch((provider) => provider.trackAgentMessageFeedback?.(metadata))\n  }\n\n  trackAgentPanelOpened(metadata: AgentPanelOpenedMetadata): void {\n    this.dispatch((provider) => provider.trackAgentPanelOpened?.(metadata))\n  }\n\n  trackAgentPanelClosed(metadata: AgentPanelClosedMetadata): void {\n    this.dispatch((provider) => provider.trackAgentPanelClosed?.(metadata))\n  }\n\n  trackAgentEntryButtonClicked(\n    metadata: AgentEntryButtonClickedMetadata\n  ): void {\n    this.dispatch((provider) =>\n      provider.trackAgentEntryButtonClicked?.(metadata)\n    )\n  }\n\n  trackAgentCloseButtonClicked(): void {\n    this.dispatch((provider) => provider.trackAgentCloseButtonClicked?.())\n  }\n\n  trackAgentConsentShown(metadata: AgentConsentShownMetadata): void {\n    this.dispatch((provider) => provider.trackAgentConsentShown?.(metadata))\n  }\n\n  trackAgentConsentResolved(metadata: AgentConsentResolvedMetadata): void {\n    this.dispatch((provider) => provider.trackAgentConsentResolved?.(metadata))\n  }\n\n  trackAgentOnboardingShown(): void {\n    this.dispatch((provider) => provider.trackAgentOnboardingShown?.())\n  }\n\n  trackAgentOnboardingStep(metadata: AgentOnboardingStepMetadata): void {\n    this.dispatch((provider) => provider.trackAgentOnboardingStep?.(metadata))\n  }\n\n  trackAgentMessageSent(metadata: AgentMessageSentMetadata): void {\n    this.dispatch((provider) => provider.trackAgentMessageSent?.(metadata))\n  }\n\n  trackAgentStarterPromptClicked(\n    metadata: AgentStarterPromptClickedMetadata\n  ): void {\n    this.dispatch((provider) =>\n      provider.trackAgentStarterPromptClicked?.(metadata)\n    )\n  }\n\n  trackAgentStarterPromptExposure(\n    metadata: AgentStarterPromptExposureMetadata\n  ): void {\n    this.dispatch((provider) =>\n      provider.trackAgentStarterPromptExposure?.(metadata)\n    )\n  }\n\n  trackAgentFreeUseNotice(metadata: AgentFreeUseNoticeMetadata): void {\n    this.dispatch((provider) => provider.trackAgentFreeUseNotice?.(metadata))\n  }\n\n  trackAgentFreeUseExposure(metadata: AgentFreeUseExposureMetadata): void {\n    this.dispatch((provider) => provider.trackAgentFreeUseExposure?.(metadata))\n  }\n\n  trackAgentNodeTagged(metadata: AgentNodeTaggedMetadata): void {\n    this.dispatch((provider) => provider.trackAgentNodeTagged?.(metadata))\n  }\n\n  trackAgentAttachButtonClicked(\n    metadata: AgentAttachButtonClickedMetadata\n  ): void {\n    this.dispatch((provider) =>\n      provider.trackAgentAttachButtonClicked?.(metadata)\n    )\n  }\n\n  trackAgentWorkflowApplied(metadata: AgentWorkflowAppliedMetadata): void {\n    this.dispatch((provider) => provider.trackAgentWorkflowApplied?.(metadata))\n  }\n\n  trackAgentGraphProjection(metadata: AgentGraphProjectionMetadata): void {\n    this.dispatch((provider) => provider.trackAgentGraphProjection?.(metadata))\n  }\n\n  // fallow-ignore-next-line unused-class-member\n  trackAgentError(metadata: AgentErrorMetadata): void {\n    this.dispatch((provider) => provider.trackAgentError?.(metadata))\n  }\n\n  trackAgentStopClicked(metadata: AgentStopClickedMetadata): void {\n    this.dispatch((provider) => provider.trackAgentStopClicked?.(metadata))\n  }\n\n  trackAgentWorkflowBound(metadata: AgentWorkflowBoundMetadata): void {\n    this.dispatch((provider) => provider.trackAgentWorkflowBound?.(metadata))\n  }\n\n  trackAgentRunApprovalShown(metadata: AgentRunApprovalShownMetadata): void {\n    this.dispatch((provider) => provider.trackAgentRunApprovalShown?.(metadata))\n  }\n\n  trackAgentRunApprovalResolved(\n    metadata: AgentRunApprovalResolvedMetadata\n  ): void {\n    this.dispatch((provider) =>\n      provider.trackAgentRunApprovalResolved?.(metadata)\n    )\n  }\n\n  trackAgentRunModeChanged(metadata: AgentRunModeChangedMetadata): void {\n    this.dispatch((provider) => provider.trackAgentRunModeChanged?.(metadata))\n  }\n\n  trackAgentThreadStarted(metadata: AgentThreadStartedMetadata): void {\n    this.dispatch((provider) => provider.trackAgentThreadStarted?.(metadata))\n  }\n\n  trackAgentConsentNotOffered(metadata: AgentConsentNotOfferedMetadata): void {\n    this.dispatch((provider) =>\n      provider.trackAgentConsentNotOffered?.(metadata)\n    )\n  }\n\n  trackAgentConsentOfferExited(\n    metadata: AgentConsentOfferExitedMetadata\n  ): void {\n    this.dispatch((provider) =>\n      provider.trackAgentConsentOfferExited?.(metadata)\n    )\n  }\n\n  trackAgentOnboardingNotShown(\n    metadata: AgentOnboardingNotShownMetadata\n  ): void {\n    this.dispatch((provider) =>\n      provider.trackAgentOnboardingNotShown?.(metadata)\n    )\n  }\n\n  trackWidgetFavoriteToggled(metadata: WidgetFavoriteToggledMetadata): void {\n    this.dispatch((provider) => provider.trackWidgetFavoriteToggled?.(metadata))\n  }\n\n  trackNamedValuesShadowDiffMismatch(\n    metadata: NamedValuesShadowDiffMismatchMetadata\n  ): void {\n    this.dispatch((provider) =>\n      provider.trackNamedValuesShadowDiffMismatch?.(metadata)\n    )\n  }\n\n  trackNamedValuesShadowDiffSummary(\n    metadata: NamedValuesShadowDiffSummaryMetadata\n  ): void {\n    this.dispatch((provider) =>\n      provider.trackNamedValuesShadowDiffSummary?.(metadata)\n    )\n  }\n\n  trackLinkDedupDrop(metadata: LinkDedupDropMetadata): void {\n    this.dispatch((provider) => provider.trackLinkDedupDrop?.(metadata))\n  }\n\n  trackPageView(pageName: string, properties?: PageViewMetadata): void {\n    this.dispatch((provider) => provider.trackPageView?.(pageName, properties))\n  }\n\n  trackFetchTimeout(metadata: FetchTimeoutMetadata): void {\n    this.dispatch((provider) => provider.trackFetchTimeout?.(metadata))\n  }\n}\n","/**\n * Survey Response Normalization Utilities\n *\n * Smart categorization system to normalize free-text survey responses\n * into standardized categories for better analytics breakdowns.\n * Uses Fuse.js for fuzzy matching against category keywords.\n */\nimport Fuse from 'fuse.js'\nimport type { SurveyResponses, SurveyResponsesNormalized } from '../types'\n\ninterface CategoryMapping {\n  name: string\n  keywords: string[]\n  userCount?: number // For reference from analysis\n}\n\n/**\n * Industry category mappings based on ~9,000 user analysis\n */\nconst INDUSTRY_CATEGORIES: CategoryMapping[] = [\n  {\n    name: 'Film / TV / Animation',\n    userCount: 2885,\n    keywords: [\n      'film',\n      'tv',\n      'television',\n      'animation',\n      'animation studio',\n      'tv production',\n      'film production',\n      'story',\n      'anime',\n      'video',\n      'cinematography',\n      'visual effects',\n      'vfx',\n      'vfx artist',\n      'movie',\n      'cinema',\n      'documentary',\n      'documentary filmmaker',\n      'broadcast',\n      'streaming',\n      'production',\n      'director',\n      'filmmaker',\n      'post-production',\n      'editing'\n    ]\n  },\n  {\n    name: 'Marketing / Advertising / Social Media',\n    userCount: 1340,\n    keywords: [\n      'marketing',\n      'advertising',\n      'youtube',\n      'tiktok',\n      'social media',\n      'content creation',\n      'influencer',\n      'brand',\n      'promotion',\n      'digital marketing',\n      'seo',\n      'campaigns',\n      'copywriting',\n      'growth',\n      'engagement'\n    ]\n  },\n  {\n    name: 'Software / IT / AI',\n    userCount: 1100,\n    keywords: [\n      'software',\n      'software development',\n      'software engineer',\n      'it',\n      'ai',\n      'ai research',\n      'corporate ai research',\n      'ai research lab',\n      'tech company ai research',\n      'developer',\n      'app developer',\n      'consulting',\n      'tech',\n      'tech startup',\n      'programmer',\n      'data science',\n      'machine learning',\n      'coding',\n      'programming',\n      'web development',\n      'app development',\n      'saas'\n    ]\n  },\n  {\n    name: 'Product & Industrial Design',\n    userCount: 1050,\n    keywords: [\n      'product design',\n      'industrial',\n      'manufacturing',\n      '3d rendering',\n      'product visualization',\n      'mechanical',\n      'automotive',\n      'cad',\n      'prototype',\n      'design engineering',\n      'invention'\n    ]\n  },\n  {\n    name: 'Fine Art / Contemporary Art',\n    userCount: 780,\n    keywords: [\n      'fine art',\n      'art',\n      'illustration',\n      'contemporary',\n      'artist',\n      'painting',\n      'drawing',\n      'sculpture',\n      'gallery',\n      'canvas',\n      'digital art',\n      'mixed media',\n      'abstract',\n      'portrait'\n    ]\n  },\n  {\n    name: 'Education / Research',\n    userCount: 640,\n    keywords: [\n      'education',\n      'student',\n      'teacher',\n      'research',\n      'university research',\n      'academic ai research',\n      'university ai research',\n      'ai research at university',\n      'learning',\n      'university',\n      'school',\n      'academic',\n      'professor',\n      'curriculum',\n      'training',\n      'instruction',\n      'pedagogy'\n    ]\n  },\n  {\n    name: 'Architecture / Engineering / Construction',\n    userCount: 420,\n    keywords: [\n      'architecture',\n      'architecture firm',\n      'construction',\n      'engineering',\n      'civil',\n      'civil engineering',\n      'cad',\n      'building',\n      'structural',\n      'landscape',\n      'landscape architecture',\n      'interior design',\n      'real estate',\n      'planning',\n      'blueprints'\n    ]\n  },\n  {\n    name: 'Gaming / Interactive Media',\n    userCount: 410,\n    keywords: [\n      'gaming',\n      'game dev',\n      'game development',\n      'indie game studio',\n      'vr development',\n      'roblox',\n      'interactive',\n      'interactive media',\n      'virtual world',\n      'vr',\n      'ar',\n      'metaverse',\n      'simulation',\n      'unity',\n      'unity developer',\n      'unreal',\n      'indie games'\n    ]\n  },\n  {\n    name: 'Photography / Videography',\n    userCount: 70,\n    keywords: [\n      'photography',\n      'photo',\n      'videography',\n      'camera',\n      'image',\n      'portrait',\n      'wedding',\n      'commercial photo',\n      'stock photography',\n      'photojournalism',\n      'event photography'\n    ]\n  },\n  {\n    name: 'Fashion / Beauty / Retail',\n    userCount: 25,\n    keywords: [\n      'fashion',\n      'fashion design',\n      'beauty',\n      'beauty industry',\n      'jewelry',\n      'jewelry design',\n      'custom jewelry design',\n      'retail',\n      'retail store',\n      'style',\n      'clothing',\n      'cosmetics',\n      'makeup',\n      'accessories',\n      'boutique'\n    ]\n  },\n  {\n    name: 'Music / Performing Arts',\n    userCount: 25,\n    keywords: [\n      'music',\n      'music production',\n      'vj',\n      'dance',\n      'projection mapping',\n      'audio visual',\n      'concert',\n      'concert production',\n      'performance',\n      'theater',\n      'stage',\n      'live events'\n    ]\n  },\n  {\n    name: 'Healthcare / Medical / Life Science',\n    userCount: 30,\n    keywords: [\n      'healthcare',\n      'medical',\n      'medical research',\n      'doctor',\n      'biotech',\n      'life science',\n      'pharmaceutical',\n      'clinical',\n      'clinical research',\n      'hospital',\n      'medicine',\n      'health'\n    ]\n  },\n  {\n    name: 'E-commerce / Print-on-Demand / Business',\n    userCount: 15,\n    keywords: [\n      'ecommerce',\n      'e-commerce',\n      'print on demand',\n      'shop',\n      'business',\n      'commercial',\n      'startup',\n      'entrepreneur',\n      'sales',\n      'online store'\n    ]\n  },\n  {\n    name: 'Nonprofit / Government / Public Sector',\n    userCount: 15,\n    keywords: [\n      '501c3',\n      'ngo',\n      'government',\n      'public service',\n      'policy',\n      'nonprofit',\n      'charity',\n      'civic',\n      'community',\n      'social impact'\n    ]\n  },\n  {\n    name: 'Adult / NSFW',\n    userCount: 10,\n    keywords: [\n      'nsfw',\n      'nsfw content',\n      'adult',\n      'adult entertainment',\n      'erotic',\n      'explicit',\n      'xxx',\n      'porn'\n    ]\n  }\n]\n\n/**\n * Use case category mappings based on common patterns\n */\nconst USE_CASE_CATEGORIES: CategoryMapping[] = [\n  {\n    name: 'Content Creation & Marketing',\n    keywords: [\n      'content creation',\n      'social media',\n      'marketing',\n      'marketing campaigns',\n      'advertising',\n      'youtube',\n      'youtube thumbnail',\n      'youtube thumbnail generation',\n      'tiktok',\n      'instagram',\n      'thumbnails',\n      'posts',\n      'campaigns',\n      'brand content'\n    ]\n  },\n  {\n    name: 'Art & Illustration',\n    keywords: [\n      'art',\n      'illustration',\n      'drawing',\n      'painting',\n      'concept art',\n      'creating concept art',\n      'character design',\n      'digital art',\n      'fantasy art',\n      'portraits'\n    ]\n  },\n  {\n    name: 'Product Visualization & Design',\n    keywords: [\n      'product',\n      'product mockup',\n      'product mockup creation',\n      'visualization',\n      'prototype visualization',\n      'design',\n      'prototype',\n      'mockup',\n      '3d rendering',\n      'industrial design',\n      'product photos'\n    ]\n  },\n  {\n    name: 'Film & Video Production',\n    keywords: [\n      'film',\n      'video',\n      'video editing',\n      'movie',\n      'movie production',\n      'animation',\n      'vfx',\n      'visual effects',\n      'storyboard',\n      'storyboard creation',\n      'cinematography',\n      'post production'\n    ]\n  },\n  {\n    name: 'Gaming & Interactive Media',\n    keywords: [\n      'game',\n      'gaming',\n      'game asset generation',\n      'game assets',\n      'game development',\n      'game textures',\n      'interactive',\n      'vr',\n      'vr content creation',\n      'ar',\n      'virtual',\n      'simulation',\n      'metaverse',\n      'textures'\n    ]\n  },\n  {\n    name: 'Architecture & Construction',\n    keywords: [\n      'architecture',\n      'architectural rendering',\n      'building',\n      'building visualization',\n      'construction',\n      'interior design',\n      'interior design mockups',\n      'landscape',\n      'real estate',\n      'real estate visualization',\n      'floor plans',\n      'renderings'\n    ]\n  },\n  {\n    name: 'Education & Training',\n    keywords: [\n      'education',\n      'educational',\n      'educational content',\n      'training',\n      'training materials',\n      'learning',\n      'teaching',\n      'tutorial',\n      'tutorial creation',\n      'course',\n      'academic',\n      'academic projects',\n      'instructional',\n      'workshops'\n    ]\n  },\n  {\n    name: 'Research & Development',\n    keywords: [\n      'research',\n      'research experiments',\n      'development',\n      'experiment',\n      'prototype',\n      'prototype testing',\n      'testing',\n      'analysis',\n      'study',\n      'innovation',\n      'innovation projects',\n      'r&d',\n      'scientific visualization'\n    ]\n  },\n  {\n    name: 'Personal & Hobby',\n    keywords: [\n      'personal',\n      'personal art projects',\n      'hobby',\n      'hobby work',\n      'fun',\n      'fun experiments',\n      'experiment',\n      'learning',\n      'curiosity',\n      'explore',\n      'creative',\n      'creative exploration',\n      'side project'\n    ]\n  },\n  {\n    name: 'Photography & Image Processing',\n    keywords: [\n      'photography',\n      'product photography',\n      'portrait photography',\n      'photo',\n      'photo editing',\n      'image',\n      'image enhancement',\n      'portrait',\n      'editing',\n      'enhancement',\n      'restoration',\n      'photo manipulation'\n    ]\n  }\n]\n\n/**\n * Fuse.js configuration for category matching\n */\nconst FUSE_OPTIONS = {\n  keys: ['keywords'],\n  threshold: 0.53, // Higher = more lenient matching\n  minMatchCharLength: 5,\n  includeScore: true,\n  includeMatches: true,\n  ignoreLocation: true,\n  findAllMatches: true\n}\n\n/**\n * Create Fuse instances for category matching\n */\nconst industryFuse = new Fuse(INDUSTRY_CATEGORIES, FUSE_OPTIONS)\nconst useCaseFuse = new Fuse(USE_CASE_CATEGORIES, FUSE_OPTIONS)\n\n/**\n * Normalize industry responses using Fuse.js fuzzy search\n */\nexport function normalizeIndustry(rawIndustry: unknown): string {\n  if (!rawIndustry || typeof rawIndustry !== 'string') {\n    return 'Other / Undefined'\n  }\n\n  const industry = rawIndustry.toLowerCase().trim()\n\n  // Handle common undefined responses\n  if (\n    industry.match(/^(other|none|undefined|unknown|n\\/a|not applicable|-|)$/)\n  ) {\n    return 'Other / Undefined'\n  }\n\n  // Fuse.js fuzzy search for best category match\n  const results = industryFuse.search(rawIndustry)\n\n  if (results.length > 0) {\n    return results[0].item.name\n  }\n\n  // No good match found - preserve original with prefix\n  return `Uncategorized: ${rawIndustry}`\n}\n\n/**\n * Normalize use case responses using Fuse.js fuzzy search\n */\nexport function normalizeUseCase(rawUseCase: unknown): string {\n  if (!rawUseCase || typeof rawUseCase !== 'string') {\n    return 'Other / Undefined'\n  }\n\n  const useCase = rawUseCase.toLowerCase().trim()\n\n  // Handle common undefined responses\n  if (\n    useCase.match(/^(other|none|undefined|unknown|n\\/a|not applicable|-|)$/)\n  ) {\n    return 'Other / Undefined'\n  }\n\n  // Fuse.js fuzzy search for best category match\n  const results = useCaseFuse.search(rawUseCase)\n\n  if (results.length > 0) {\n    return results[0].item.name\n  }\n\n  // No good match found - preserve original with prefix\n  return `Uncategorized: ${rawUseCase}`\n}\n\n/**\n * Apply normalization to survey responses\n * Creates both normalized and raw versions of responses\n */\nexport function normalizeSurveyResponses(\n  responses: SurveyResponses\n): SurveyResponsesNormalized {\n  const normalized: SurveyResponsesNormalized = { ...responses }\n\n  // Normalize industry\n  if (typeof responses.industry === 'string') {\n    normalized.industry_normalized = normalizeIndustry(responses.industry)\n    normalized.industry_raw = responses.industry\n  }\n\n  // Normalize use case\n  if (typeof responses.useCase === 'string') {\n    normalized.useCase_normalized = normalizeUseCase(responses.useCase)\n    normalized.useCase_raw = responses.useCase\n  }\n\n  return normalized\n}\n","import {\n  getBillingTelemetryEventName,\n  getBillingTelemetryEventPayload\n} from '@comfyorg/account-core/billing'\nimport type { BillingTelemetryEvent } from '@comfyorg/account-core/billing'\nimport type {\n  ComfyDesktop2TelemetryBridge,\n  ComfyDesktop2TelemetryValue\n} from '@comfyorg/comfyui-desktop-bridge-types'\nimport type {\n  AddCreditsClickMetadata,\n  AgentAttachButtonClickedMetadata,\n  AgentConsentNotOfferedMetadata,\n  AgentConsentOfferExitedMetadata,\n  AgentConsentResolvedMetadata,\n  AgentConsentShownMetadata,\n  AgentCreditTransitionNoticeMetadata,\n  AgentEntryButtonClickedMetadata,\n  AgentFreeUseExposureMetadata,\n  AgentFreeUseNoticeMetadata,\n  AgentGraphProjectionMetadata,\n  AgentMessageFeedbackMetadata,\n  AgentMessageSentMetadata,\n  AgentNodeTaggedMetadata,\n  AgentOnboardingNotShownMetadata,\n  AgentOnboardingStepMetadata,\n  AgentPanelClosedMetadata,\n  AgentPanelOpenedMetadata,\n  AgentPaywallCtaMetadata,\n  AgentPaywallShownMetadata,\n  AgentRunApprovalResolvedMetadata,\n  AgentRunApprovalShownMetadata,\n  AgentRunModeChangedMetadata,\n  AgentStarterPromptClickedMetadata,\n  AgentStarterPromptExposureMetadata,\n  AgentStopClickedMetadata,\n  AgentThreadStartedMetadata,\n  AgentWorkflowBoundMetadata,\n  AgentWorkflowAppliedMetadata,\n  AuthMetadata,\n  BeginCheckoutMetadata,\n  DefaultViewSetMetadata,\n  EnterLinearMetadata,\n  ExecutionErrorMetadata,\n  ExecutionSuccessMetadata,\n  HelpCenterClosedMetadata,\n  HelpCenterOpenedMetadata,\n  HelpResourceClickedMetadata,\n  LinkDedupDropMetadata,\n  NamedValuesShadowDiffMismatchMetadata,\n  NamedValuesShadowDiffSummaryMetadata,\n  NodeAddedMetadata,\n  NodeSearchMetadata,\n  NodeSearchResultMetadata,\n  PageViewMetadata,\n  PageVisibilityMetadata,\n  RunButtonProperties,\n  SearchQueryMetadata,\n  SettingChangedMetadata,\n  ShareFlowMetadata,\n  ShareLinkOpenedMetadata,\n  SharedWorkflowRunMetadata,\n  ResubscribeClickMetadata,\n  SubscriptionCancellationMetadata,\n  SubscriptionMetadata,\n  SubscriptionSuccessMetadata,\n  SurveyResponses,\n  TabCountMetadata,\n  TelemetryEventName,\n  TelemetryProvider,\n  TemplateFilterMetadata,\n  TemplateLibraryClosedMetadata,\n  TemplateLibraryMetadata,\n  TemplateMetadata,\n  UiButtonClickMetadata,\n  WorkflowCreatedMetadata,\n  WorkflowImportMetadata,\n  WorkflowSavedMetadata\n} from '../../types'\nimport { CANCELLATION_STAGE_EVENTS, TelemetryEvents } from '../../types'\nimport { normalizeSurveyResponses } from '../../utils/surveyNormalization'\n\ntype HostTelemetryProperties = Parameters<\n  ComfyDesktop2TelemetryBridge['capture']\n>[1]\n\nfunction isHostTelemetryPrimitive(\n  value: unknown\n): value is ComfyDesktop2TelemetryValue {\n  return (\n    value === null ||\n    typeof value === 'string' ||\n    typeof value === 'number' ||\n    typeof value === 'boolean'\n  )\n}\n\nfunction toHostTelemetryProperties(\n  properties?: object\n): HostTelemetryProperties {\n  if (!properties) return undefined\n\n  const out: NonNullable<HostTelemetryProperties> = {}\n  for (const [key, value] of Object.entries(properties)) {\n    if (isHostTelemetryPrimitive(value)) {\n      out[key] = value\n    } else if (Array.isArray(value) && value.every(isHostTelemetryPrimitive)) {\n      out[key] = value\n    }\n  }\n\n  return out\n}\n\nexport class HostTelemetrySink implements TelemetryProvider {\n  private capture(event: TelemetryEventName, properties?: object): void {\n    window.__comfyDesktop2?.Telemetry?.capture(\n      event,\n      toHostTelemetryProperties(properties)\n    )\n  }\n\n  trackSignupOpened(): void {\n    this.capture(TelemetryEvents.USER_SIGN_UP_OPENED)\n  }\n\n  trackAuth(metadata: AuthMetadata): void {\n    this.capture(TelemetryEvents.USER_AUTH_COMPLETED, metadata)\n  }\n\n  trackUserLoggedIn(): void {\n    this.capture(TelemetryEvents.USER_LOGGED_IN)\n  }\n\n  trackSubscription(\n    event: 'modal_opened' | 'subscribe_clicked',\n    metadata?: SubscriptionMetadata\n  ): void {\n    this.capture(\n      event === 'modal_opened'\n        ? TelemetryEvents.SUBSCRIPTION_REQUIRED_MODAL_OPENED\n        : TelemetryEvents.SUBSCRIBE_NOW_BUTTON_CLICKED,\n      metadata\n    )\n  }\n\n  trackBeginCheckout(metadata: BeginCheckoutMetadata): void {\n    this.capture(TelemetryEvents.BEGIN_CHECKOUT, metadata)\n  }\n\n  trackBillingEvent(event: BillingTelemetryEvent): void {\n    this.capture(\n      getBillingTelemetryEventName(event),\n      getBillingTelemetryEventPayload(event)\n    )\n  }\n\n  trackMonthlySubscriptionSucceeded(\n    metadata?: SubscriptionSuccessMetadata\n  ): void {\n    this.capture(TelemetryEvents.MONTHLY_SUBSCRIPTION_SUCCEEDED, metadata)\n  }\n\n  trackMonthlySubscriptionCancelled(): void {\n    this.capture(TelemetryEvents.MONTHLY_SUBSCRIPTION_CANCELLED)\n  }\n\n  trackSubscriptionCancellation(\n    event: 'flow_opened' | 'confirmed' | 'abandoned' | 'failed',\n    metadata?: SubscriptionCancellationMetadata\n  ): void {\n    this.capture(CANCELLATION_STAGE_EVENTS[event], metadata)\n  }\n\n  trackResubscribeClicked(metadata: ResubscribeClickMetadata): void {\n    this.capture(TelemetryEvents.RESUBSCRIBE_BUTTON_CLICKED, metadata)\n  }\n\n  trackAddApiCreditButtonClicked(metadata?: AddCreditsClickMetadata): void {\n    this.capture(TelemetryEvents.ADD_API_CREDIT_BUTTON_CLICKED, metadata)\n  }\n\n  trackAgentPaywallShown(metadata: AgentPaywallShownMetadata): void {\n    this.capture(TelemetryEvents.AGENT_PAYWALL_SHOWN, metadata)\n  }\n\n  trackAgentPaywallCtaClicked(metadata: AgentPaywallCtaMetadata): void {\n    this.capture(TelemetryEvents.AGENT_PAYWALL_CTA_CLICKED, metadata)\n  }\n\n  trackAgentCreditTransitionNotice(\n    metadata: AgentCreditTransitionNoticeMetadata\n  ): void {\n    this.capture(TelemetryEvents.AGENT_CREDIT_TRANSITION_NOTICE, metadata)\n  }\n\n  trackApiCreditTopupButtonPurchaseClicked(amount: number): void {\n    this.capture(TelemetryEvents.API_CREDIT_TOPUP_BUTTON_PURCHASE_CLICKED, {\n      credit_amount: amount\n    })\n  }\n\n  trackApiCreditTopupSucceeded(): void {\n    this.capture(TelemetryEvents.API_CREDIT_TOPUP_SUCCEEDED)\n  }\n\n  trackRunButton(properties: RunButtonProperties): void {\n    this.capture(TelemetryEvents.RUN_BUTTON_CLICKED, properties)\n  }\n\n  trackSurvey(\n    stage: 'opened' | 'submitted',\n    responses?: SurveyResponses\n  ): void {\n    this.capture(\n      stage === 'opened'\n        ? TelemetryEvents.USER_SURVEY_OPENED\n        : TelemetryEvents.USER_SURVEY_SUBMITTED,\n      responses ? normalizeSurveyResponses(responses) : undefined\n    )\n  }\n\n  trackEmailVerification(stage: 'opened' | 'requested' | 'completed'): void {\n    const event =\n      stage === 'opened'\n        ? TelemetryEvents.USER_EMAIL_VERIFY_OPENED\n        : stage === 'requested'\n          ? TelemetryEvents.USER_EMAIL_VERIFY_REQUESTED\n          : TelemetryEvents.USER_EMAIL_VERIFY_COMPLETED\n    this.capture(event)\n  }\n\n  trackTemplate(metadata: TemplateMetadata): void {\n    this.capture(TelemetryEvents.TEMPLATE_WORKFLOW_OPENED, metadata)\n  }\n\n  trackTemplateLibraryOpened(metadata: TemplateLibraryMetadata): void {\n    this.capture(Tele